import * as THREE from './product/vendor/three.module.js';
import {GLTFLoader} from './product/vendor/GLTFLoader.js';
const host=document.getElementById('homeObject'),canvas=document.getElementById('homeCanvas');
let expanded=false;host.addEventListener('pointerenter',()=>expanded=true);host.addEventListener('pointerleave',()=>expanded=false);host.addEventListener('click',()=>expanded=!expanded);host.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();expanded=!expanded}});host.addEventListener('focus',()=>expanded=true);host.addEventListener('blur',()=>expanded=false);
async function init(){
 const renderer=new THREE.WebGLRenderer({canvas,alpha:true,antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;
 const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(36,1,.01,100);camera.position.set(9,6,10);camera.lookAt(0,0,0);scene.add(new THREE.HemisphereLight(0xffffff,0x27422d,2));const light=new THREE.DirectionalLight(0xffffff,3);light.position.set(5,8,6);scene.add(light);
 const response=await fetch('voron/assembly.glb.gz');if(!response.ok)throw Error('model');const data=await new Response(response.body.pipeThrough(new DecompressionStream('gzip'))).arrayBuffer();const gltf=await new GLTFLoader().parseAsync(data,'voron/');const model=gltf.scene;const box=new THREE.Box3().setFromObject(model),center=box.getCenter(new THREE.Vector3()),size=box.getSize(new THREE.Vector3());const wrapper=new THREE.Group();model.position.sub(center);wrapper.add(model);wrapper.scale.setScalar(6/Math.max(size.x,size.y,size.z));scene.add(wrapper);const nodes=model.children.map((node,i)=>({node,base:node.position.clone(),offset:new THREE.Vector3(Math.sin(i*2.4),((i%5)-2)*.5,Math.cos(i*2.4)).multiplyScalar(Math.max(size.x,size.y,size.z)*.16)}));
 new ResizeObserver(()=>{const w=host.clientWidth,h=host.clientHeight;renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix()}).observe(host);canvas.style.opacity=1;document.getElementById('heroFallback').style.opacity=0;
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;let value=0;function draw(){requestAnimationFrame(draw);if(document.body.dataset.page!=='home')return;value+=(Number(expanded)-value)*(reduced?1:.07);for(const p of nodes)p.node.position.copy(p.base).addScaledVector(p.offset,value);wrapper.rotation.y=-.25+value*.1;renderer.render(scene,camera)}draw();
}init().catch(()=>{canvas.style.display='none'});
